CREATE TABLE IF NOT EXISTS procurement_vendors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, legal_name text NOT NULL, jurisdiction text NOT NULL DEFAULT 'Nigeria', vendor_category text, registration_reference text, tax_reference text, beneficial_owner_status text NOT NULL DEFAULT 'Not Verified', due_diligence_status text NOT NULL DEFAULT 'Pending', sanctions_screening_status text NOT NULL DEFAULT 'Pending', conflict_status text NOT NULL DEFAULT 'Pending', risk_rating text NOT NULL DEFAULT 'Unassessed', approved_vendor boolean NOT NULL DEFAULT false, evidence_reference text, status text NOT NULL DEFAULT 'Draft', notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS procurement_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, request_title text NOT NULL, department text, requester text, category text, estimated_amount numeric, currency text DEFAULT 'NGN', procurement_method text NOT NULL DEFAULT 'To Be Determined', budget_reference text, authority_route text, approval_status text NOT NULL DEFAULT 'Draft', status text NOT NULL DEFAULT 'Open', justification text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS procurement_evaluations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid REFERENCES procurement_requests(id), vendor_id uuid REFERENCES procurement_vendors(id), technical_score numeric, commercial_score numeric, compliance_score numeric, total_score numeric, evaluator text, evaluation_status text NOT NULL DEFAULT 'Draft', evidence_reference text, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS procurement_contracts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, vendor_id uuid REFERENCES procurement_vendors(id), request_id uuid REFERENCES procurement_requests(id), contract_title text NOT NULL, contract_type text, contract_value numeric, currency text DEFAULT 'NGN', start_date date, end_date date, renewal_date date, owner_role text, approval_status text NOT NULL DEFAULT 'Draft', legal_review_status text NOT NULL DEFAULT 'Pending', signature_status text NOT NULL DEFAULT 'Not Signed', performance_status text NOT NULL DEFAULT 'Not Started', document_reference text, status text NOT NULL DEFAULT 'Active', notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS procurement_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, request_id uuid REFERENCES procurement_requests(id), vendor_id uuid REFERENCES procurement_vendors(id), contract_id uuid REFERENCES procurement_contracts(id), po_number text, amount numeric, currency text DEFAULT 'NGN', approval_status text NOT NULL DEFAULT 'Pending', issue_status text NOT NULL DEFAULT 'Draft', evidence_reference text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS vendor_performance_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vendor_id uuid REFERENCES procurement_vendors(id), contract_id uuid REFERENCES procurement_contracts(id), review_period date NOT NULL, delivery_score numeric, quality_score numeric, compliance_score numeric, overall_score numeric, reviewer text, status text NOT NULL DEFAULT 'Draft', notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS procurement_controls (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, control_name text NOT NULL, control_level text NOT NULL DEFAULT 'High', control_description text NOT NULL, approval_route text, evidence_required text, frequency text, status text NOT NULL DEFAULT 'Active');
INSERT INTO procurement_controls(entity_name,control_name,control_level,control_description,approval_route,evidence_required,frequency) SELECT 'OSANVAULT AFRICA LTD','Vendor due diligence','Critical','No strategic or high-risk vendor should be approved without identity, registration, beneficial ownership, sanctions and conflict checks appropriate to its risk.','Procurement + Compliance','Corporate records, ownership evidence, screening results and due diligence record','Before approval / periodic refresh' WHERE NOT EXISTS (SELECT 1 FROM procurement_controls WHERE control_name='Vendor due diligence');
INSERT INTO procurement_controls(entity_name,control_name,control_level,control_description,approval_route,evidence_required,frequency) SELECT 'OSANVAULT AFRICA LTD','Three-way match','Critical','Where applicable, invoice payment should reconcile approved purchase order, receipt/performance evidence and invoice before payment authorization.','Finance + Procurement','PO, receipt/service acceptance and invoice','Per invoice' WHERE NOT EXISTS (SELECT 1 FROM procurement_controls WHERE control_name='Three-way match');
INSERT INTO procurement_controls(entity_name,control_name,control_level,control_description,approval_route,evidence_required,frequency) SELECT 'OSANVAULT AFRICA LTD','Contract legal review','High','Material or non-standard contracts require legal review before execution.','Legal / Compliance + delegated business owner','Contract, legal comments and approval record','Before signature' WHERE NOT EXISTS (SELECT 1 FROM procurement_controls WHERE control_name='Contract legal review');
INSERT INTO procurement_controls(entity_name,control_name,control_level,control_description,approval_route,evidence_required,frequency) SELECT 'OSANVAULT AFRICA LTD','Conflict-of-interest declaration','High','Procurement participants and relevant approvers must disclose conflicts and recuse where appropriate.','Compliance / governance route','Signed declaration and recusal record where applicable','Per event / annual refresh' WHERE NOT EXISTS (SELECT 1 FROM procurement_controls WHERE control_name='Conflict-of-interest declaration');
INSERT INTO procurement_controls(entity_name,control_name,control_level,control_description,approval_route,evidence_required,frequency) SELECT 'OSANVAULT AFRICA LTD','Contract renewal control','High','Contracts approaching expiry require performance review, commercial review and renewed authority before extension.','Contract owner + Procurement + Legal as applicable','Performance review, renewal recommendation and approval','Before renewal' WHERE NOT EXISTS (SELECT 1 FROM procurement_controls WHERE control_name='Contract renewal control');